import{_ as r,a0 as o,w as h,s as l,I as i,x as a,a1 as t,A as p,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse(`{"title":"在 Ubuntu 上配置高性能的 HHVM 环境 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 上配置高性能的 HHVM 环境 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 上配置高性能的 HHVM 环境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 上配置高性能的 HHVM 环境 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150901 Setting Up High-Performance 'HHVM' and Nginx or Apache with MariaDB on Debian or Ubuntu","title":"在 Ubuntu 上配置高性能的 HHVM 环境","tag":"201509","desc":""},"relativePath":"201509/20150901 Setting Up High-Performance 'HHVM' and Nginx or Apache with MariaDB on Debian or Ubuntu.md","filePath":"[post].md"}`),d={name:"201509/20150901 Setting Up High-Performance 'HHVM' and Nginx or Apache with MariaDB on Debian or Ubuntu.md"};function c(m,e,g,u,H,x){const n=o("Link");return h(),l("div",null,[e[16]||(e[16]=i("h1",{id:"在-ubuntu-上配置高性能的-hhvm-环境",tabindex:"-1"},[a("在 Ubuntu 上配置高性能的 HHVM 环境 "),i("a",{class:"header-anchor",href:"#在-ubuntu-上配置高性能的-hhvm-环境","aria-label":"Permalink to “在 Ubuntu 上配置高性能的 HHVM 环境”"},"​")],-1)),i("p",null,[e[1]||(e[1]=a("HHVM全称为 HipHop Virtual Machine，它是一个开源虚拟机，用来运行由 Hack(一种编程语言)和 PHP 开发应用。HHVM 在保证了 PHP 程序员最关注的高灵活性的要求下，通过使用最新的编译方式来取得了非凡的性能。到目前为止，相对于 PHP + ",-1)),t(n,{href:"http://www.tecmint.com/install-apc-alternative-php-cache-in-rhel-centos-fedora/"},{default:p(()=>[...e[0]||(e[0]=[a("APC (Alternative PHP Cache)",-1)])]),_:1}),e[2]||(e[2]=a(" ，HHVM 为 FaceBook 在 HTTP 请求的吞吐量上提高了9倍的性能，在内存的占用上，减少了5倍左右的内存占用。",-1))]),e[17]||(e[17]=s(`<p>同时，HHVM 也可以与基于 FastCGI 的 Web 服务器（如 Nginx 或者 Apache ）协同工作。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-HHVM-Nginx-Apache-MariaDB.png" alt="Install HHVM, Nginx and Apache with MariaDB"></p><p><em>安装 HHVM，Nginx和 Apache 还有 MariaDB</em></p><p>在本教程中，我们一起来配置 Nginx/Apache web 服务器、 数据库服务器 MariaDB 和 HHVM 。我们将使用 Ubuntu 15.04 (64 位)，因为 HHVM 只能运行在64位系统上。同时，该教程也适用于 Debian 和 Linux Mint。</p><h3 id="第一步-安装-nginx-或者-apache-服务器" tabindex="-1">第一步: 安装 Nginx 或者 Apache 服务器 <a class="header-anchor" href="#第一步-安装-nginx-或者-apache-服务器" aria-label="Permalink to “第一步: 安装 Nginx 或者 Apache 服务器”">​</a></h3><p>1、首先，先进行一次系统的升级并更新软件仓库列表，命令如下</p><pre><code># apt-get update &amp;&amp; apt-get upgrade
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/System-Upgrade.png" alt="System Upgrade"></p><p><em>系统升级</em></p><p>2、 正如我之前说的，HHVM 能和 Nginx 和 Apache 进行集成。所以，究竟使用哪个服务器，这是你的自由，不过，我们会教你如何安装这两个服务器。</p><h4 id="安装-nginx" tabindex="-1">安装 Nginx <a class="header-anchor" href="#安装-nginx" aria-label="Permalink to “安装 Nginx”">​</a></h4><p>我们通过下面的命令安装 Nginx/Apache 服务器</p><pre><code># apt-get install nginx
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-Nginx-Web-Server.png" alt="Install Nginx Web Server"></p><p><em>安装 Nginx 服务器</em></p><h4 id="安装-apache" tabindex="-1">安装 Apache <a class="header-anchor" href="#安装-apache" aria-label="Permalink to “安装 Apache”">​</a></h4><pre><code># apt-get install apache2
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-Apache-Web-Server.png" alt="Install Apache Web Server"></p><p><em>安装 Apache 服务器</em></p><p>完成这一步，你能通过以下的链接看到 Nginx 或者 Apache 的默认页面</p><pre><code>http://localhost
或
http://IP-Address
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Nginx-Welcome-Page.png" alt="Nginx Welcome Page"></p><p><em>Nginx 默认页面</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Apache-Default-Page.png" alt="Apache Default Page"></p><p><em>Apache 默认页面</em></p><h3 id="第二步-安装和配置-mariadb" tabindex="-1">第二步: 安装和配置 MariaDB <a class="header-anchor" href="#第二步-安装和配置-mariadb" aria-label="Permalink to “第二步: 安装和配置 MariaDB”">​</a></h3><p>3、 这一步，我们将通过如下命令安装 MariaDB，它是一个比 MySQL 性能更好的数据库</p><pre><code># apt-get install mariadb-client mariadb-server
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Install-MariaDB-Database.png" alt="Install MariaDB Database"></p><p><em>安装 MariaDB</em></p><p>4、 在 MariaDB 成功安装之后，你可以启动它，并且设置 root 密码来保护数据库:</p><pre><code># systemctl start mysql
# mysql_secure_installation
</code></pre><p>回答以下问题，只需要按下<code>y</code>或者 <code>n</code>并且回车。请确保你仔细的阅读过说明。</p><pre><code>Enter current password for root (enter for none) = press enter
Set root password? [Y/n] = y
Remove anonymous users[y/n] = y
Disallow root login remotely[y/n] = y
Remove test database and access to it [y/n] = y
Reload privileges tables now[y/n] = y
</code></pre><p>5、 在设置了密码之后，你就可以登录 MariaDB 了。</p><pre><code># mysql -u root -p
</code></pre><h3 id="第三步-安装-hhvm" tabindex="-1">第三步: 安装 HHVM <a class="header-anchor" href="#第三步-安装-hhvm" aria-label="Permalink to “第三步: 安装 HHVM”">​</a></h3><p>6、 在此阶段，我们将安装 HHVM。我们需要添加 HHVM 的仓库到你的<code>sources.list</code>文件中，然后更新软件列表。</p><pre><code># wget -O - http://dl.hhvm.com/conf/hhvm.gpg.key | apt-key add -
# echo deb http://dl.hhvm.com/ubuntu DISTRIBUTION_VERSION main | sudo tee /etc/apt/sources.list.d/hhvm.list
# apt-get update
</code></pre><p><strong>重要</strong>：不要忘记用你的 Ubuntu 发行版代号替换上述的 DISTRIBUTION_VERSION (比如：lucid, precise, trusty) 或者是 Debian 的 jessie 或者 wheezy。在 Linux Mint 中也是一样的，不过只支持 petra。</p><p>添加了 HHVM 仓库之后，你就可以轻松安装了。</p><pre><code># apt-get install -y hhvm
</code></pre><p>安装之后，就可以启动它，但是它并没有做到开机启动。可以用如下命令做到开机启动。</p><pre><code># update-rc.d hhvm defaults
</code></pre><h3 id="第四步-配置-nginx-apache-连接-hhvm" tabindex="-1">第四步: 配置 Nginx/Apache 连接 HHVM <a class="header-anchor" href="#第四步-配置-nginx-apache-连接-hhvm" aria-label="Permalink to “第四步: 配置 Nginx/Apache 连接 HHVM”">​</a></h3><p>7、 现在，nginx/apache 和 HHVM 都已经安装完成了，并且都独立运行起来了，所以我们需要对它们进行设置，来让它们互相关联。这个关键的步骤，就是需要告知 nginx/apache 将所有的 php 文件，都交给 HHVM 进行处理。</p><p>如果你用了 Nginx，请按照如下步骤：</p><p>nginx 的配置文件在 /etc/nginx/sites-available/default， 并且这些配置文件会在 /usr/share/nginx/html 中寻找文件执行，不过，它不知道如何处理 PHP。</p><p>为了确保 Nginx 可以连接 HHVM，我们需要执行所带的如下脚本。它可以帮助我们正确的配置 Nginx，将 hhvm.conf 放到 上面提到的配置文件 nginx.conf 的头部。</p><p>这个脚本可以确保 Nginx 可以对 .hh 和 .php 的做正确的处理，并且将它们通过 fastcgi 发送给 HHVM。</p><pre><code># /usr/share/hhvm/install_fastcgi.sh
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Configure-Nginx-for-HHVM.png" alt="Configure Nginx for HHVM"></p><p><em>配置 Nginx、HHVM</em></p><p><strong>重要</strong>: 如果你使用的是 Apache，这里不需要进行配置。</p><p>8、 接下来，你需要使用 hhvm 来提供 php 的运行环境。</p><pre><code># /usr/bin/update-alternatives --install /usr/bin/php php /usr/bin/hhvm 60
</code></pre><p>以上步骤完成之后，你现在可以启动并且测试它了。</p><pre><code># systemctl start hhvm
</code></pre><h3 id="第五步-测试-hhvm-和-nginx-apache" tabindex="-1">第五步: 测试 HHVM 和 Nginx/Apache <a class="header-anchor" href="#第五步-测试-hhvm-和-nginx-apache" aria-label="Permalink to “第五步: 测试 HHVM 和 Nginx/Apache”">​</a></h3><p>9、 为了确认 hhvm 是否工作，你需要在 nginx/apache 的文档根目录下建立 hello.php。</p><pre><code># nano /usr/share/nginx/html/hello.php       [对于 Nginx]
或
# nano /var/www/html/hello.php               [对于 Nginx 和 Apache]
</code></pre><p>在文件中添加如下代码:</p><pre><code>&lt;?php
if (defined(&#39;HHVM_VERSION&#39;)) {
    echo &#39;HHVM is working&#39;;
    phpinfo();
} else {
    echo &#39;HHVM is not working&#39;;
}
?&gt;
</code></pre><p>然后访问如下链接，确认自己能否看到 &quot;hello world&quot;</p><pre><code>http://localhost/info.php
或
http://IP-Address/info.php
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/HHVM-Page.png" alt="HHVM Page"></p><p><em>HHVM 页面</em></p><p>如果 “HHVM” 的页面出现了，那就说明你成功了。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>以上的步骤都是非常简单的，希望你能觉得这是一篇有用的教程，如果你在以上的步骤中遇到了问题，给我们留一个评论，我们将全力解决。</p><hr>`,71)),i("p",null,[e[4]||(e[4]=a("via: ",-1)),t(n,{href:"http://www.tecmint.com/install-hhvm-and-nginx-apache-with-mariadb-on-debian-ubuntu/"},{default:p(()=>[...e[3]||(e[3]=[a("http://www.tecmint.com/install-hhvm-and-nginx-apache-with-mariadb-on-debian-ubuntu/",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=a("作者：",-1)),t(n,{href:"http://www.tecmint.com/author/admin/"},{default:p(()=>[...e[5]||(e[5]=[a("Ravi Saive",-1)])]),_:1}),e[9]||(e[9]=a(" 译者：",-1)),t(n,{href:"https://github.com/MikeCoder"},{default:p(()=>[...e[6]||(e[6]=[a("MikeCoder",-1)])]),_:1}),e[10]||(e[10]=a(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:p(()=>[...e[7]||(e[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[11]||(e[11]=[a("LCTT",-1)])]),_:1}),e[14]||(e[14]=a(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:p(()=>[...e[12]||(e[12]=[a("Linux中国",-1)])]),_:1}),e[15]||(e[15]=a(" 荣誉推出",-1))])])}const f=r(d,[["render",c]]);export{b as __pageData,f as default};
